
from typing import Literal, TypedDict


class ResearchPlan(TypedDict):
    """Structured research plan generated by the Planner Agent."""

    goal: str
    tasks: list[str]


class Source(TypedDict):
    """Structured information about a research source."""

    title: str
    url: str
    source_type: Literal["Wikipedia article", "arXiv research paper"]
    authors: list[str]
    published: str
    content: str


class AgentState(TypedDict):
    """Shared state of the multi-agent research workflow."""

    query: str
    plan: ResearchPlan
    research_material: str
    sources: list[Source]
    analysis: str
    fact_check: str
    final_report: str
